    let phase = Math.trunc((pos - whole) * BL_PHASES);
    if (phase >= BL_PHASES) phase = BL_PHASES - 1;
    const first = whole - BL_TAPS / 2 + 1;
    const over = first + BL_TAPS - this.consumed - (BL_MASK + 1);
    if (over > 0) this.consume(over);
